dexes // cannot polute events to each other, accidentally or maliciously. let pre_cancellation_window = config.pre_cancellation_window_secs; let pre_cancellation_tracker = table::new(); pre_cancellation_tracker.add( PRE_CANCELLATION_TRACKER_KEY, new_pre_cancellation_tracker(pre_cancellation_window) ); let dead_mans_switch_tracker = table::new(); dead_mans_switch_tracker.add( DEAD_MANS_SWITCH_TRACKER_KEY, new_dead_mans_switch_tracker(config.min_keep_alive_time_secs) ); Market::V1 { parent: signer::address_of(parent), market: signer::address_of(market), config, order_book: new_order_book(), pre_cancellation_tracker, dead_mans_switch_tracker }\\n}","breadcrumbs":"market_types » Function new_market","id":"5344","title":"Function new_market"},"5345":{"body":"public fun set_allow_self_trade<M: copy, drop, store>(self: & mut market_types::Market<M>, allow_self_trade: bool) Implementation public fun set_allow_self_trade<M: store + copy + drop>( self: & mut Market<M>, allow_self_trade: bool\\n) { self.config.allow_self_trade = allow_self_trade;\\n}","breadcrumbs":"market_types » Function set_allow_self_trade","id":"5345","title":"Function set_allow_self_trade"},"5346":{"body":"public fun set_allow_events_emission<M: copy, drop, store>(self: & mut market_types::Market<M>, allow_events_emission: bool) Implementation public fun set_allow_events_emission<M: store + copy + drop>( self: & mut Market<M>, allow_events_emission: bool\\n) { self.config.allow_events_emission = allow_events_emission;\\n}","breadcrumbs":"market_types » Function set_allow_events_emission","id":"5346","title":"Function set_allow_events_emission"},"5347":{"body":"public fun set_allow_dead_mans_switch<M: copy, drop, store>(self: & mut market_types::Market<M>, enable_dead_mans_switch: bool) Implementation public fun set_allow_dead_mans_switch<M: store + copy + drop>( self: & mut Market<M>, enable_dead_mans_switch: bool\\n) { self.config.enable_dead_mans_switch = enable_dead_mans_switch;\\n}","breadcrumbs":"market_types » Function set_allow_dead_mans_switch","id":"5347","title":"Function set_allow_dead_mans_switch"},"5348":{"body":"public fun set_dead_mans_switch_min_keep_alive_time_secs<M: copy, drop, store>(self: & mut market_types::Market<M>, min_keep_alive_time_secs: u64) Implementation public fun set_dead_mans_switch_min_keep_alive_time_secs<M: store + copy + drop>( self: & mut Market<M>, min_keep_alive_time_secs: u64\\n) { self.config.min_keep_alive_time_secs = min_keep_alive_time_secs; let parent = self.parent; let market = self.market; dead_mans_switch_tracker::set_min_keep_alive_time_secs( self. get_dead_mans_switch_tracker_mut(), parent, market, min_keep_alive_time_secs );\\n}","breadcrumbs":"market_types » Function set_dead_mans_switch_min_keep_alive_time_secs","id":"5348","title":"Function set_dead_mans_switch_min_keep_alive_time_secs"},"5349":{"body":"public fun get_order_book<M: copy, drop, store>(self: & market_types::Market<M>): & order_book::OrderBook<M> Implementation public fun get_order_book<M: store + copy + drop>(self: & Market<M>): &OrderBook<M> { &self. order_book\\n}","breadcrumbs":"market_types » Function get_order_book","id":"5349","title":"Function get_order_book"},"535":{"body":"public fun index_of<T>(self: & big_vector::BigVector<T>, val: &T): (bool, u64) pragma opaque; aborts_if false; ensures result_1 ==> result_2 < self. length(); ensures result_1 ==> spec_at(self, result_2) == val; ensures !result_1 ==> ( forall j in 0.. spec_table_len(self.buckets): forall k in 0..len( table_with_length::spec_get(self.buckets, j)): table_with_length::spec_get(self.buckets, j)[k] != val);","breadcrumbs":"big_vector » Function index_of","id":"535","title":"Function index_of"},"5350":{"body":"public fun get_market_address<M: copy, drop, store>(self: & market_types::Market<M>): address Implementation public fun get_market_address<M: store + copy + drop>(self: & Market<M>): address { self.market\\n}","breadcrumbs":"market_types » Function get_market_address"